const test = require('node:test')
const assert = require('node:assert/strict')
const crypto = require('node:crypto')
const fs = require('node:fs')
const path = require('node:path')

const {
  createArtifact,
  createManifest,
} = require('../scripts/run-visual-bundle.js')

const outputDirectory = path.join(__dirname, '..', 'experiments', 'output')

test('Beta 0.2 artifact is deterministic, explainable, and front-end ready', () => {
  const first = createArtifact()
  const replay = createArtifact()

  assert.deepEqual(first, replay)
  assert.equal(first.artifactVersion, 'visual-data-beta0.2')
  assert.equal(first.bundle.timeline.dayCount, 42)
  assert.equal(first.bundle.encoding.agentOrder.length, 125)
  assert.equal(first.bundle.channels.frontDrivers.status, 'available')
  assert.equal(first.bundle.channels.reverseVoice.status, 'unavailable')
  assert.equal(first.bundle.channels.relationEdges.status, 'unavailable')
  assert.equal(first.bundle.timeline.delta.aggregateRisk.at(-1), -27.67)
})

test('checked-in Beta 0.2 artifact and manifest match generated bytes', () => {
  const artifactPath = path.join(outputDirectory, 'visual-data-beta0.2.json')
  const manifestPath = path.join(outputDirectory, 'visual-data-beta0.2-manifest.json')
  const artifactBytes = fs.readFileSync(artifactPath)
  const checkedInArtifact = JSON.parse(artifactBytes.toString('utf8'))
  const checkedInManifest = JSON.parse(fs.readFileSync(manifestPath, 'utf8'))
  const generatedArtifact = createArtifact()
  const generatedBytes = Buffer.from(`${JSON.stringify(generatedArtifact)}\n`)

  assert.deepEqual(checkedInArtifact, generatedArtifact)
  assert.deepEqual(checkedInManifest, createManifest(generatedBytes))
  assert.equal(checkedInManifest.byteLength, artifactBytes.byteLength)
  assert.equal(
    checkedInManifest.sha256,
    crypto.createHash('sha256').update(artifactBytes).digest('hex'),
  )
})
